PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT DISTINCT ?pub ?doi ?title ?toc ?year ?type WHERE {
 VALUES ?toc { <https://dblp.org/db/conf/mm/mm2024> <https://dblp.org/db/conf/mrac/mrac2024> <https://dblp.org/db/conf/sumac-ws/sumac2024> }
 ?pub dblp:listedOnTocPage ?toc ; dblp:title ?title ; dblp:yearOfPublication ?year ; a ?type .
 FILTER(?type IN (dblp:Inproceedings, dblp:Article, dblp:Incollection))
 OPTIONAL { ?pub dblp:doi ?doi }
} ORDER BY ?pub
